effect.shader:
const int MAX_STEPS = 96;

void main() {
    vec4 color = texture(inputImg, acScreenNorm);

    float rad = radians(angle);
    // Em pixels da COMPOSIÇÃO: `acEscalaDePixel` converte para o buffer, e a prévia
    // reduzida (o Auto da tela, o play) fica do tamanho da exportação (0.516.0).
    vec2 axis = vec2(cos(rad), sin(rad)) * acTexelSize * (reach * acEscalaDePixel);
    int steps = clamp(int(quality + 0.5), 1, MAX_STEPS);

    float shadow = 0.0;
    for (int i = 1; i <= MAX_STEPS; i++) {
        if (i > steps) break;
        float t = float(i) / float(steps);
        vec2 uv = acScreenNorm - axis * t;
        if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) continue;

        float hit = texture(inputImg, uv).a;
        // O desvanecer é aplicado no PASSO, não no fim: assim a sombra perde
        // força conforme se afasta do objeto, em vez de clarear por igual.
        shadow = max(shadow, hit * mix(1.0, 1.0 - t, fade));
    }

    vec4 thrown = vec4(shadowColor.rgb, shadow * shadowColor.a * opacityF);

    // A camada por cima da sombra, com a fórmula de alpha reto. A sombra tem que
    // ficar ATRÁS: composta por cima, ela escureceria o próprio objeto.
    float outAlpha = color.a + thrown.a * (1.0 - color.a);
    vec3 outColor = outAlpha > 0.0
        ? (color.rgb * color.a + thrown.rgb * thrown.a * (1.0 - color.a)) / outAlpha
        : vec3(0.0);

    fragColor = vec4(outColor, outAlpha);
}
